<script setup>
import Avatar from './Avatar.vue'
import Icon from './Icon.vue'
import {state as s,roomParticipants,roomStatus,togetherTotalLabel,togetherTotalCompact} from './state.js'
defineProps({compact:Boolean})
defineEmits(['open'])
</script>
<template><button class="room-badge" :class="{compact,'mini-room':compact,'player-room':!compact,connected:!!s.room.id,offline:s.room.id&&!s.room.connected}" :aria-label="s.room.id?'一起听房间':'邀请听友一起听'" :title="roomStatus+' · '+roomParticipants.map(m=>m.name).join(' / ')+(s.room.id&&roomParticipants.length>1?' · 累计 '+togetherTotalLabel:'')" @click="$emit('open')"><span class="room-avatars"><Avatar v-for="m in roomParticipants" :key="m.id" :src="m.avatar" :name="m.name" :size="compact?26:30" /><span v-if="s.room.id&&roomParticipants.length<2" class="avatar-invite" title="等待听友加入"><Icon name="plus" :size="compact?13:16" /></span><Icon v-if="!roomParticipants.length" name="headphones" :size="compact?19:22" /></span><span class="room-copy"><strong>{{s.room.id?roomParticipants.map(m=>m.name).join(' · '):'邀请听友一起听'}}</strong><small role="status"><i v-if="s.room.id"></i>{{s.room.id?roomStatus:'单人播放 · 与手机网易云同步'}}<span v-if="s.room.id&&roomParticipants.length>1" class="room-total-full"> · {{s.togetherStats.totalSeconds!==null?'累计 '+togetherTotalLabel:s.togetherStats.loading?'同步累计时长…':'累计时长暂不可用'}}</span><Icon name="right" :size="12" /></small></span><Icon v-if="compact&&!s.room.id&&roomParticipants.length" class="invite-mark" name="headphones" :size="12" /><span v-if="compact&&s.room.id&&roomParticipants.length>1" class="room-total-compact">{{s.togetherStats.totalSeconds!==null?togetherTotalCompact:s.togetherStats.loading?'同步中':'时长待同步'}}</span><i v-if="compact&&s.room.id" class="compact-room-dot"></i></button></template>
